style.css:
@-moz-document domain("roblox.com") {
/* Set the main background image */
    body, 
    .dark-theme, 
    .light-theme {
        background-image: url('https://i.imgur.com/9gFxJCI.png') !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* Make main content containers transparent to reveal the image */
    .content, 
    .container-main, 
    .footer-container,
    #container-main,
    .wrapper {
        background: transparent !important;
    }

    /* Blend side panels, navigation, and cards into a matching deep blue transparent tint */
    .rbx-left-col, 
    .left-col-container,
    .section-content, 
    .game-card-container, 
    .item-card-container,
    .places-list-container,
    .roblox-popover-content,
    .dropdown-menu,
    .mcl-list-container {
        background: rgba(18, 22, 54, 0.6) !important; /* Semi-transparent midnight blue */
        border: 1px solid rgba(48, 59, 114, 0.3) !important; /* Subtle matching border */
    }

    /* Adjust the top navigation bar to match the aesthetic */
    #header, 
    .rbx-header {
        background: rgba(14, 17, 43, 0.8) !important;
        backdrop-filter: blur(5px) !important; /* Adds a modern blur effect behind the header */
    }

    /* Ensure text stands out against the dark blue theme */
    .text-title, 
    .text-name, 
    h1, h2, h3 {
        color: #d1d5ff !important; /* Light pastel blue text */
    }
}
